// src/lib/indexableCities.ts
// Curated set of city pages submitted to Google (sitemap + index,follow).
// Generated by `node scripts/build-indexable-cities.js` (verified 200 + self-canonical),
// plus the 100 world cities featured on the homepage grid.
// City pages NOT in this set still render for visitors but are served `noindex`
// until they gain real content. Re-run the script after importing new reports/facts.
import list from "@/data/indexableCities.json";
import top100 from "@/data/top100cities.json";

export type IndexableCity = {
  slug: string;
  name: string;
  admin1: string;
  country: string;
  country_code: string;
};

const merged = new Map<string, IndexableCity>();
for (const c of top100 as Array<Partial<IndexableCity> & { slug: string; name: string }>) {
  merged.set(c.slug.toLowerCase(), {
    slug: c.slug.toLowerCase(),
    name: c.name,
    admin1: c.admin1 || "",
    country: c.country || "",
    country_code: c.country_code || "",
  });
}
for (const c of list as IndexableCity[]) {
  if (!merged.has(c.slug.toLowerCase())) merged.set(c.slug.toLowerCase(), c);
}

export const INDEXABLE_CITIES: IndexableCity[] = [...merged.values()];

const SLUGS = new Set(merged.keys());

export function isIndexableCitySlug(slug?: string | null): boolean {
  if (!slug) return false;
  try {
    return SLUGS.has(decodeURIComponent(slug).toLowerCase().trim());
  } catch {
    return SLUGS.has(slug.toLowerCase().trim());
  }
}
